const story = $('Fetch Approved Stories').first().json;
const fetched = $('Fetch Linked Assets').all().map(x => x.json);
const downloaded = $input.all().map(x => x.json);
const byIndex = new Map();
for (let i = 0; i < fetched.length; i++) {
  const a = { ...fetched[i], imageBase64: (downloaded[i] && downloaded[i].imageBase64) || '' };
  const idx = Number(a['Slide Index']);
  if (idx >= 1 && idx <= 7) byIndex.set(idx, a);
}
const assets = [...byIndex.entries()].sort((a, b) => a[0] - b[0]).map(([, a]) => a);
if (assets.length === 0) throw new Error('No Assets with Slide Index 1-7 found for Story ' + story.id);
return [{
  json: {
    storyId: story.id,
    title: story.Title,
    pillar: story.Pillar,
    story,
    assets,
    xThread: {
      post1: (story.Title || '') + ' — ' + (story.Glance || ''),
      post2: (story.Remember || '') + ' (1/2 → 2/2)'
    }
  }
}];

// #!/usr/bin/env node
"use strict";

const THEMES = {
  "archival-warm": {
    bg: "#181816",
    cardBg: "#F6F4EF",
    cardBorder: "#DDD8CC",
    surfaceText: "#171715",
    surfaceBody: "#2F2F2B",
    surfaceMuted: "#5E5D58",
    accentOnDark: "#F5B841",
    accentOnLight: "#B45309",
    isDarkCard: false
  },
  "museum-stone": {
    bg: "#1C1917",
    cardBg: "#F3EFE6",
    cardBorder: "#D6CFC2",
    surfaceText: "#1C1917",
    surfaceBody: "#37332E",
    surfaceMuted: "#6B655E",
    accentOnDark: "#FBBF24",
    accentOnLight: "#92400E",
    isDarkCard: false
  },
  "blueprint-slate": {
    bg: "#0F172A",
    cardBg: "#F8FAFC",
    cardBorder: "#CBD5E1",
    surfaceText: "#0F172A",
    surfaceBody: "#334155",
    surfaceMuted: "#475569",
    accentOnDark: "#38BDF8",
    accentOnLight: "#0369A1",
    isDarkCard: false
  },
  "terminal-mono": {
    bg: "#111315",
    cardBg: "#171A1F",
    cardBorder: "#2B3038",
    surfaceText: "#F4F4F5",
    surfaceBody: "#D4D4D8",
    surfaceMuted: "#9CA3AF",
    accentOnDark: "#60A5FA",
    accentOnLight: "#60A5FA",
    isDarkCard: true
  }
};

const BODY_FONT = "Helvetica Neue, Inter, sans-serif";
const SERIF_FONT = "Georgia, 'Times New Roman', serif";

function esc(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function splitSentences(text) {
  return String(text || "").trim().replace(/\s+/g, " ").split(/(?<=[.!?])\s+/).filter(Boolean);
}

function fitCompleteSentences(text, maxWords) {
  const sentences = splitSentences(text);
  if (!sentences.length) return String(text || "").trim();
  const kept = [];
  let count = 0;
  for (const s of sentences) {
    const words = s.replace(/\*\*/g, "").split(/\s+/).filter(Boolean).length;
    if (kept.length === 0 || count + words <= maxWords) {
      kept.push(s);
      count += words;
    } else {
      break;
    }
  }
  return kept.join(" ");
}

function tokenizeRichWords(text, budget) {
  const cap = budget || { remaining: 3 };
  const cleaned = String(text || "").trim();
  const tokens = [];
  const regex = /\*\*([^*]+)\*\*/g;
  let lastIndex = 0;

  function pushSegment(seg, wantBold, attachLeadingPunct) {
    const plain = seg.replace(/\*/g, "");
    const words = plain.split(/\s+/).filter(Boolean);
    for (let wi = 0; wi < words.length; wi++) {
      const w = words[wi];
      const noSpace = Boolean(attachLeadingPunct && wi === 0 && /^[.,;:!?)]/.test(w) && !/^\s/.test(seg));
      const bold = Boolean(wantBold && cap.remaining > 0);
      if (bold) cap.remaining -= 1;
      tokens.push({ text: w, bold, noSpace });
    }
  }

  let match;
  while ((match = regex.exec(cleaned)) !== null) {
    if (match.index > lastIndex) {
      pushSegment(cleaned.slice(lastIndex, match.index), false, lastIndex > 0);
    }
    pushSegment(match[1], true, false);
    lastIndex = regex.lastIndex;
  }
  if (lastIndex < cleaned.length) {
    pushSegment(cleaned.slice(lastIndex), false, lastIndex > 0);
  }
  return tokens;
}

function wrapRichLines(text, maxChars, maxLines, budget) {
  const tokens = tokenizeRichWords(text, budget);
  const lines = [];
  let curTokens = [];
  let curLen = 0;
  for (const tok of tokens) {
    const addLen = (curLen && !tok.noSpace ? 1 : 0) + tok.text.length;
    if (!curLen || tok.noSpace || curLen + addLen <= maxChars) {
      curTokens.push(tok);
      curLen += addLen;
    } else {
      lines.push(curTokens);
      curTokens = [tok];
      curLen = tok.text.length;
      if (maxLines && lines.length >= maxLines) break;
    }
  }
  if (curTokens.length && (!maxLines || lines.length < maxLines)) {
    lines.push(curTokens);
  }
  return lines;
}

function renderRichTspans(lineTokens, accentColor) {
  const spans = [];
  for (let i = 0; i < lineTokens.length; i++) {
    const tok = lineTokens[i];
    const prefix = (i === 0 || tok.noSpace) ? "" : " ";
    if (tok.bold) {
      spans.push(`<tspan font-weight="700" fill="${accentColor}">${esc(prefix + tok.text)}</tspan>`);
    } else {
      spans.push(esc(prefix + tok.text));
    }
  }
  return spans.join("");
}

function buildParagraphBlocks(paragraphs, maxChars, maxTotalLines, budget) {
  const blocks = [];
  let used = 0;
  for (const p of paragraphs) {
    const clean = String(p || "").trim();
    if (!clean) continue;
    const remaining = maxTotalLines - used;
    if (remaining <= 0) break;
    const lines = wrapRichLines(clean, maxChars, remaining, budget);
    if (lines.length) {
      blocks.push(lines);
      used += lines.length;
    }
  }
  return blocks;
}

function parseJsonOutput(rawItem) {
  if (!rawItem || rawItem.error) return null;
  let obj = rawItem;
  if (!Array.isArray(obj.slides)) {
    const rawText = (obj.content?.parts?.map(p => p.text || "").join("") || obj.text || obj.output || "").replace(/```(?:json)?/g, "").trim();
    if (!rawText) return null;
    try {
      obj = JSON.parse(rawText);
    } catch {
      return null;
    }
  }
  if (!obj || !Array.isArray(obj.slides) || obj.slides.length < 4) return null;
  return obj;
}

function sanitizeCta(rawCta) {
  const cleaned = String(rawCta || "").replace(/\*\*/g, "").replace(/\*/g, "").trim();
  if (!cleaned) return "Which design story next?";
  if (cleaned.includes("·")) {
    const parts = cleaned.split("·").map(s => s.trim()).filter(Boolean);
    const q = parts.find(s => s.endsWith("?")) || parts[parts.length - 1];
    return q || "Which design story next?";
  }
  return cleaned;
}

function sanitizeEyebrow(raw) {
  const cleaned = String(raw || "").replace(/\*\*/g, "").replace(/\*/g, "").trim();
  if (!cleaned) return "";
  return cleaned.length > 26 ? cleaned.slice(0, 26).trim() : cleaned;
}

function buildNarrativeSections(story, count) {
  const glanceSentences = splitSentences(story.Glance);
  const exploreParas = String(story.Explore || "").split(/\n+/).map(s => s.trim()).filter(Boolean);
  const deepParas = String(story["Deep Dive"] || "").split(/\n+/).map(s => s.trim()).filter(Boolean);
  const rememberText = String(story.Remember || "").trim();

  const coverSubtitle = fitCompleteSentences(glanceSentences[0] || "", 20);
  const sections = [
    { kind: "cover", heading: String(story.Title || "").trim(), paragraphs: coverSubtitle ? [coverSubtitle] : [] }
  ];

  const bodyPool = [];
  if (glanceSentences.length > 1) {
    bodyPool.push({ heading: "Built to Outlast", paragraphs: [fitCompleteSentences(glanceSentences.slice(1).join(" "), 35)] });
  }
  for (const p of exploreParas) {
    const sents = splitSentences(p);
    if (sents.length >= 4) {
      const mid = Math.ceil(sents.length / 2);
      bodyPool.push({ heading: "How It Worked", paragraphs: [fitCompleteSentences(sents.slice(0, mid).join(" "), 35)] });
      bodyPool.push({ heading: "Why It Mattered", paragraphs: [fitCompleteSentences(sents.slice(mid).join(" "), 35)] });
    } else {
      bodyPool.push({ heading: "How It Worked", paragraphs: [fitCompleteSentences(p, 35)] });
    }
  }
  for (const p of deepParas) {
    const sents = splitSentences(p);
    if (sents.length >= 4) {
      const mid = Math.ceil(sents.length / 2);
      bodyPool.push({ heading: "The Clever Detail", paragraphs: [fitCompleteSentences(sents.slice(0, mid).join(" "), 35)] });
      bodyPool.push({ heading: "Craft in Practice", paragraphs: [fitCompleteSentences(sents.slice(mid).join(" "), 35)] });
    } else {
      bodyPool.push({ heading: "The Clever Detail", paragraphs: [fitCompleteSentences(p, 35)] });
    }
  }

  const middleSlots = Math.max(0, count - 2);
  for (let i = 0; i < middleSlots; i++) {
    sections.push(bodyPool[i] || { heading: String(story.Title || "The Story"), paragraphs: [fitCompleteSentences(story.Explore || story.Glance || "", 35)] });
  }

  if (count >= 2) {
    sections.push({
      kind: "legacy",
      heading: "What Still Endures",
      paragraphs: [fitCompleteSentences(rememberText || story.Glance || "", 30)],
      cta: "Which design story next?"
    });
  }

  return sections.slice(0, count);
}

const BODY_LAYOUTS = ["split_top_photo", "photo_bottom_scrim", "inset_museum_card", "split_bottom_photo"];
const COVER_LAYOUTS = new Set(["cover_hero", "cover_framed"]);
const VALID_BODY_LAYOUTS = new Set(BODY_LAYOUTS);

function buildCarouselSlides(story, assets, polished, designPlan) {
  if (!story || !story.Title) throw new Error("Missing Story Title");
  const byIndex = new Map();
  for (const a of (assets || [])) {
    const idx = Number(a["Slide Index"]);
    if (idx >= 1 && idx <= 7) byIndex.set(idx, a);
  }
  const maxAssetIdx = byIndex.size ? Math.max(...byIndex.keys()) : 0;
  const totalSlides = Math.max(4, maxAssetIdx || 6);
  const fallbackSections = buildNarrativeSections(story, totalSlides);
  const polishedByIdx = new Map();
  if (polished && Array.isArray(polished.slides)) {
    for (const ps of polished.slides) {
      polishedByIdx.set(Number(ps.slide_index), ps);
    }
  }
  const designByIdx = new Map();
  if (designPlan && Array.isArray(designPlan.slides)) {
    for (const ds of designPlan.slides) {
      designByIdx.set(Number(ds.slide_index), ds);
    }
  }

  const themeKey = (designPlan && THEMES[designPlan.theme_palette]) ? designPlan.theme_palette : "archival-warm";
  const headingFont = (designPlan && designPlan.heading_style === "editorial-serif") ? SERIF_FONT : BODY_FONT;

  const slides = [];
  let prevBodyLayout = "";
  for (let i = 1; i <= totalSlides; i++) {
    const asset = byIndex.get(i) || null;
    const ps = polishedByIdx.get(i) || null;
    const ds = designByIdx.get(i) || null;
    const sec = fallbackSections[i - 1] || { kind: "body", heading: story.Title, paragraphs: [] };
    const hasPhoto = Boolean(asset && (asset.imageBase64 || (Array.isArray(asset.File) && asset.File[0] && asset.File[0].url)));
    const isCover = i === 1;
    const isLast = i === totalSlides;
    const heading = (ps && ps.headline) ? String(ps.headline) : sec.heading;
    const rawBody = (ps && ps.body) ? String(ps.body) : sec.paragraphs.join(" ");
    const bodyText = fitCompleteSentences(rawBody, isCover ? 22 : isLast ? 30 : 35);
    const cta = isLast ? sanitizeCta((polished && polished.cta) || sec.cta) : "";
    const eyebrow = sanitizeEyebrow(ds && ds.eyebrow);

    let layout = "card";
    if (hasPhoto) {
      if (isCover) {
        layout = (ds && COVER_LAYOUTS.has(ds.layout)) ? ds.layout : "cover_hero";
      } else if (isLast) {
        layout = "legacy_closing";
      } else {
        let chosen = (ds && VALID_BODY_LAYOUTS.has(ds.layout)) ? ds.layout : BODY_LAYOUTS[(i - 2) % BODY_LAYOUTS.length];
        if (chosen === prevBodyLayout) {
          chosen = BODY_LAYOUTS[(BODY_LAYOUTS.indexOf(chosen) + 1) % BODY_LAYOUTS.length];
        }
        prevBodyLayout = chosen;
        layout = chosen;
      }
    }

    slides.push({
      slideIndex: i,
      totalSlides,
      kind: isCover ? "cover" : isLast ? "legacy" : "body",
      layout,
      themeKey,
      headingFont,
      eyebrow,
      pillar: String(story.Pillar || "WE, HUMANITY").toUpperCase(),
      heading,
      paragraphs: bodyText ? [bodyText] : [],
      cta,
      credit: asset ? asset.Credit : "",
      assetName: asset ? (asset.Name || "") : "",
      license: asset ? (asset.License || "") : "",
      aiGenerated: Boolean(asset && asset["AI Generated"]),
      imageBase64: asset ? (asset.imageBase64 || "") : "",
      imageMime: (asset && Array.isArray(asset.File) && asset.File[0] && asset.File[0].type) || "image/jpeg",
      imageUrl: (asset && Array.isArray(asset.File) && asset.File[0] && asset.File[0].url) || ""
    });
  }
  return slides;
}

function formatShortSlideCredit(slide) {
  if (slide.aiGenerated) return "";
  const raw = String(slide.credit || "").trim();
  if (!raw) return "";
  if (raw.length <= 56 && !raw.includes("via Wikimedia") && !raw.includes("http")) return raw;

  const titleMatch = raw.match(/^"([^"]+)"/);
  const title = titleMatch ? titleMatch[1] : "";
  const byMatch = raw.match(/"\s+by\s+(.+?)\s+via\s+(Wikimedia Commons|Openverse)/i)
    || raw.match(/"\s+by\s+(.+?),\s*(CC0|public domain)/i);
  let author = byMatch ? byMatch[1].trim() : "";

  const assumed = author.match(/([A-Z][\w.-]+)\s+assumed/i);
  if (assumed) author = assumed[1];
  author = author
    .replace(/^No machine-readable author provided\.?\s*/i, "")
    .replace(/\(based on copyright claims\)\.?/gi, "")
    .replace(/^(?:User:|Original:\s*User:)/i, "")
    .replace(/^Unknown(?:\s+(?:author|artist))+$/i, "Unknown")
    .replace(/(Unknown\s+(?:author|artist))\1+/i, "Unknown")
    .replace(/\s+from\s+[^,]+(?:,\s*[^,]+)?$/i, "")
    .trim();
  if (!author || /^unknown$/i.test(author)) author = "";

  let inst = "";
  if (/^NAMA\b|National Archaeological Museum|Národní archeologické/i.test(title) || /\bNAMA\b/.test(title)) {
    inst = "NAMA";
  } else if (/British Museum|\bBM\b|Brit Mus/i.test(title)) {
    inst = "British Museum";
  } else if (/Science Museum/i.test(title)) {
    inst = "Science Museum";
  } else if (/Metropolitan Museum|\bMET\b/i.test(title)) {
    inst = "The Met";
  } else if (/Louvre/i.test(title)) {
    inst = "Louvre";
  }

  let lic = String(slide.license || "").trim();
  if (!lic) {
    const licMatch = raw.match(/licensed under\s+(CC\s+BY(?:-SA)?(?:\s+\d+(?:\.\d+)?)?)/i);
    if (licMatch) lic = licMatch[1];
    else if (/\bCC0\b/i.test(raw)) lic = "CC0";
    else if (/public domain/i.test(raw)) lic = "Public domain";
  }
  lic = lic
    .replace(/^CC\s+BY-SA(?:\s+\d+(?:\.\d+)?)?$/i, "CC BY-SA")
    .replace(/^CC\s+BY(?:\s+\d+(?:\.\d+)?)?$/i, "CC BY")
    .replace(/^Public domain$/i, "Public domain");

  const isReplica = /\b(model|replica|reconstruction)\b/i.test(title + " " + (slide.assetName || ""));
  const who = [inst, author].filter(Boolean).join(" / ") || "Wikimedia Commons";
  const base = [who, lic].filter(Boolean).join(", ");
  return isReplica ? `${base} (modern replica)` : base;
}

function renderEyebrowPill(eyebrow, x, y, onDark, theme) {
  if (!eyebrow) return "";
  const label = eyebrow.toUpperCase();
  const w = Math.min(440, Math.max(140, label.length * 10.5 + 36));
  const bgFill = onDark ? "#FFFFFF" : theme.surfaceText;
  const bgOpacity = onDark ? "0.14" : "0.08";
  const strokeOpacity = onDark ? "0.35" : "0.22";
  const textFill = onDark ? theme.accentOnDark : theme.accentOnLight;
  return `<g transform="translate(${x}, ${y})">
    <rect x="0" y="0" width="${w}" height="34" rx="17" fill="${bgFill}" fill-opacity="${bgOpacity}" stroke="${bgFill}" stroke-opacity="${strokeOpacity}" stroke-width="1"/>
    <text x="${Math.round(w / 2)}" y="22" text-anchor="middle" fill="${textFill}" font-family="${BODY_FONT}" font-size="14" font-weight="700" letter-spacing="1.5">${esc(label)}</text>
  </g>`;
}

function renderSlideSvg(slide) {
  const theme = THEMES[slide.themeKey] || THEMES["archival-warm"];
  const headFont = slide.headingFont || BODY_FONT;
  const slideCounter = String(slide.slideIndex).padStart(2, "0") + " / " + String(slide.totalSlides).padStart(2, "0");
  const highlightBudget = { remaining: 3 };

  const imgHref = slide.imageBase64
    ? ("data:" + slide.imageMime + ";base64," + slide.imageBase64)
    : (slide.imageUrl ? esc(slide.imageUrl) : "");
  const creditShort = formatShortSlideCredit(slide);

  const swipeBadgeDark = slide.slideIndex === 1
    ? `<g transform="translate(836, 1216)">
        <rect x="0" y="0" width="164" height="44" rx="22" fill="#0B0B0A" fill-opacity="0.62" stroke="#FFFFFF" stroke-opacity="0.45" stroke-width="1.5"/>
        <text x="82" y="29" text-anchor="middle" fill="#FFFFFF" font-family="${BODY_FONT}" font-size="19" font-weight="700" letter-spacing="1">Swipe →</text>
      </g>`
    : "";

  const swipeBadgeSurface = slide.slideIndex === 1
    ? `<g transform="translate(836, 1236)">
        <rect x="0" y="0" width="164" height="44" rx="22" fill="${theme.surfaceText}" fill-opacity="0.08" stroke="${theme.surfaceText}" stroke-opacity="0.3" stroke-width="1.5"/>
        <text x="82" y="29" text-anchor="middle" fill="${theme.surfaceText}" font-family="${BODY_FONT}" font-size="19" font-weight="700" letter-spacing="1">Swipe →</text>
      </g>`
    : "";

  const cardAccent = theme.isDarkCard ? theme.accentOnDark : theme.accentOnLight;
  const layout = imgHref ? slide.layout : "card";

  // 1. Text-only fallback card
  if (layout === "card") {
    const headingLines = wrapRichLines(slide.heading, 24, 4, highlightBudget);
    const paraBlocks = buildParagraphBlocks(slide.paragraphs, 44, 12, highlightBudget);
    const headLH = 62;
    const bodyLH = 46;
    const paraGap = 24;
    let bodyLinesCount = 0;
    for (const b of paraBlocks) bodyLinesCount += b.length;
    const bodyH = bodyLinesCount * bodyLH + Math.max(0, paraBlocks.length - 1) * paraGap;
    const cleanCta = slide.cta ? sanitizeCta(slide.cta) : "";
    const ctaH = cleanCta ? 80 : 0;
    const totalH = headingLines.length * headLH + 28 + bodyH + ctaH;
    const startY = Math.max(220, Math.round((1350 - totalH) / 2));

    const headEls = headingLines.map((l, i) =>
      `<text x="84" y="${startY + i * headLH}" fill="${theme.surfaceText}" font-family="${headFont}" font-size="52" font-weight="700" letter-spacing="-0.8">${renderRichTspans(l, cardAccent)}</text>`
    ).join("\n  ");
    let curY = startY + headingLines.length * headLH + 34;
    const bodyEls = [];
    for (const block of paraBlocks) {
      for (const line of block) {
        bodyEls.push(`<text x="84" y="${curY}" fill="${theme.surfaceBody}" font-family="${BODY_FONT}" font-size="33" font-weight="400">${renderRichTspans(line, cardAccent)}</text>`);
        curY += bodyLH;
      }
      curY += paraGap;
    }
    if (cleanCta) {
      const ctaBoxW = Math.min(912, Math.max(320, cleanCta.length * 13 + 56));
      bodyEls.push(`<g transform="translate(84, ${curY + 8})">
        <rect x="0" y="0" width="${ctaBoxW}" height="50" rx="25" fill="${theme.surfaceText}" fill-opacity="0.07" stroke="${theme.surfaceText}" stroke-opacity="0.35" stroke-width="1.5"/>
        <text x="${Math.round(ctaBoxW / 2)}" y="33" text-anchor="middle" fill="${theme.surfaceText}" font-family="${BODY_FONT}" font-size="23" font-weight="600">${esc(cleanCta)}</text>
      </g>`);
    }
    return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350">
  <rect width="1080" height="1350" fill="${theme.cardBg}"/>
  <rect x="36" y="36" width="1008" height="1278" rx="16" fill="none" stroke="${theme.cardBorder}" stroke-width="2"/>
  <text x="84" y="96" fill="${cardAccent}" font-family="${BODY_FONT}" font-size="18" font-weight="700" letter-spacing="2">${esc(slide.eyebrow || slide.pillar)}</text>
  <text x="996" y="96" text-anchor="end" fill="${theme.surfaceMuted}" font-family="${BODY_FONT}" font-size="22" font-weight="600" letter-spacing="2">${esc(slideCounter)}</text>
  ${headEls}
  ${bodyEls.join("\n  ")}
  <text x="84" y="1274" fill="${theme.surfaceText}" font-family="${BODY_FONT}" font-size="22" font-weight="700" letter-spacing="2">WE, HUMANITY</text>
  ${swipeBadgeSurface}
</svg>`;
  }

  // 2. Framed Cover (ideal for horizontal specimens, UI screens, or maps)
  if (layout === "cover_framed") {
    const titleLines = wrapRichLines(slide.heading, 22, 4, highlightBudget);
    const subLines = slide.paragraphs[0] ? wrapRichLines(slide.paragraphs[0], 46, 3, highlightBudget) : [];
    const titleLH = 68;
    const subLH = 38;
    const startY = slide.eyebrow ? 846 : 806;
    const titleEls = titleLines.map((l, i) =>
      `<text x="80" y="${startY + i * titleLH}" fill="${theme.surfaceText}" font-family="${headFont}" font-size="58" font-weight="700" letter-spacing="-1.1">${renderRichTspans(l, cardAccent)}</text>`
    ).join("\n  ");
    const subStartY = startY + titleLines.length * titleLH + 16;
    const subEls = subLines.map((l, i) =>
      `<text x="80" y="${subStartY + i * subLH}" fill="${theme.surfaceBody}" font-family="${BODY_FONT}" font-size="28" font-weight="400">${renderRichTspans(l, cardAccent)}</text>`
    ).join("\n  ");

    return `<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350">
  <defs>
    <clipPath id="coverFrameClip"><rect x="80" y="124" width="920" height="610" rx="20"/></clipPath>
  </defs>
  <rect width="1080" height="1350" fill="${theme.cardBg}"/>
  <text x="80" y="84" fill="${theme.surfaceText}" font-family="${BODY_FONT}" font-size="24" font-weight="700" letter-spacing="3">WH</text>
  <text x="1000" y="84" text-anchor="end" fill="${theme.surfaceMuted}" font-family="${BODY_FONT}" font-size="22" font-weight="600" letter-spacing="2">${esc(slideCounter)}</text>
